function tone(kind='match'){if(!sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;const notes=kind==='line'?[392,494,587]:kind==='win'?[392,494,587,784]:[294,349];notes.forEach((hz,i)=>{let o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=hz;o.connect(g);g.connect(audioContext.destination);let start=now+i*.05;g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.035,start+.01);g.gain.exponentialRampToValueAtTime(.001,start+.18);o.start(start);o.stop(start+.2);});}catch{sound=false;}}
function getConfig(){let raw=Number($('#seedInput').value);let seed=Number.isFinite(raw)?Math.min(99999999,Math.max(1,Math.floor(raw))):2718;$('#seedInput').value=seed;return{...DEFAULT_RULES,seed,mode:$('input[name=mode]:checked').value,prepEnabled:$('#prepToggle').checked,prepSeconds:Number($('#prepDuration').value),leaderHero:Number($('#leaderChoice').value)};}
function remaining(){return state.paused?state.pauseRemaining:Math.min(state.phase==='prep'?state.rules.prepSeconds:state.rules.battleSeconds,Math.max(0,(state.deadline-clock())/1000));}
