function startNew(random=false){if(state&&!state.finished&&state.phase==='battle'&&battleElapsed()>3)record(false,'abandoned');generation++;$('.action-announcement')?.remove();clearTimeout(freeResolveTimer);$('#chainDamage')?.remove();if(random)$('#seedInput').value=1+Math.floor(Math.random()*999999);const rules=getConfig(),rng=seededRandom(rules.seed);state={rules,rng,board:newBoard(rules,rng),hp:rules.enemyHP,phase:rules.prepEnabled?'prep':'battle',deadline:clock()+(rules.prepEnabled?rules.prepSeconds:rules.battleSeconds)*1000,paused:false,pauseRemaining:0,locked:false,finished:false,paintStock:3,leaderUsed:false,totalDamage:0,lineDamage:0,lineCount:0,matchCount:0,moves:0,prepMoves:0,prepUsed:0,maxChain:0,chain:0,emptyMoves:0,pauses:0,charges:[45,45,45],events:[],recordId:null};state.prepAim=false;state.skillTarget=null;state.skillNotice='';state.skillClock=0;state.skillTick=clock();state.skillReadyAt=[0,0,0];state.casting=[false,false,false];state.skillDamage=0;state.skillUses=[0,0,0];state.combo=0;state.rawAttackDamage=0;state.comboRemaining=0;state.comboTick=clock();state.feverUntil=0;state.score=0;state.resolving=false;state.resolvePending=false;state.pendingVisual=new Map();$('#board').replaceChildren();$('#board').dataset.audit='[]';state.ids=state.board.map((_,i)=>String(i));state.nextId=42;lastCountdown=null;$('#game').querySelector('.phase-countdown')?.remove();selected=null;paint=null;leaderRemaining=0;$('#screenOverlay').hidden=true;$('#pauseBtn').textContent='Ⅱ';$('#modeTitle').textContent=modeNames[rules.mode];$('#modeDescription').textContent=modeDescriptions[rules.mode];$('#battleBanner').textContent=rules.prepEnabled?'첫 공격을 준비하세요':'';$('#statusText').textContent=rules.prepEnabled?'원하는 두 돌을 자유롭게 교환해 첫 라인을 준비하세요.':'라인은 강하게, 3매치는 짧게 공격해요.';render();announceEntry(state.phase);$('.apply-note').textContent='현재 조건이 적용되어 있어요.';setTimeout(()=>{if(!state.finished&&!state.paused)$('#battleBanner').textContent='';},1900);}
function auditResolution(entry){const board=$('#board');let log=[];try{log=JSON.parse(board.dataset.audit||'[]');}catch{}log.push(entry);board.dataset.audit=JSON.stringify(log.slice(-20));}
function render(){renderBoard();renderHUD();renderTools();}
function renderBoard(falling=false,previous=null,action=null){const board=$('#board'),valid=new Set(state.ids),existing=new Map([...board.querySelectorAll('.tile')].map(el=>[el.dataset.uid,el]));for(const [uid,el]of existing)if(!valid.has(uid))el.remove();board.classList.toggle('locked',state.locked||state.finished||state.paused);state.board.forEach((color,i)=>{let button=existing.get(state.ids[i]);if(!button){button=document.createElement('button');const img=document.createElement('img');img.alt='';img.draggable=false;button.append(img);}button.className='tile'+(selected===i?' selected':'')+(falling?' falling':'');button.dataset.index=i;button.dataset.color=color;if(leaderRemaining&&color!==(state.rules.leaderHero===0?0:1)&&color<state.rules.colors)button.classList.add('leader-target');button.dataset.uid=state.ids[i];for(const cls of state.pendingVisual.get(state.ids[i])||[])button.classList.add(cls);button.style.setProperty('--row',Math.floor(i/state.rules.columns));button.setAttribute('aria-label',`${Math.floor(i/state.rules.columns)+1}행 ${i%state.rules.columns+1}열 ${names[color]} 돌`);button.setAttribute('aria-pressed',String(selected===i));button.disabled=state.finished||state.paused;const img=button.querySelector('img'),src=`assets/stone-${color}${color>=6?"-v2":color===4?"-unified-v4":"-unified-v1"}.png`;if(img.getAttribute('src')!==src)img.src=src;if(color>=6)button.classList.add('item-stone');const at=board.querySelectorAll('.tile')[i];if(at!==button)board.insertBefore(button,at||null);});if(previous)animateStones(board,previous,action);$('#inputHint').textContent=state.skillTarget!==null?`${SKILLS[state.skillTarget].name} · ${SKILLS[state.skillTarget].axis==='row'?'행':'열'}을 선택하세요`:state.prepAim?'리더 스킬 · 정렬할 행을 선택하세요':leaderRemaining?`리더 스킬 · ${state.rules.leaderHero===0?'불':'물'}로 바꿀 돌 ${leaderRemaining}개 선택`:paint!==null?`${names[paint]}로 바꿀 돌을 선택하세요`:(state.phase==='prep'?'자유 배치 · 원하는 두 돌을 탭하거나 드래그':hints[state.rules.mode]);}
function renderHUD(){tickSkills();renderSkillHUD();renderPuzzleMeter();let time=remaining();$('#timer').textContent=state.finished?'0.0':time.toFixed(1);$('#phaseLabel').textContent=state.phase==='prep'?'준비':'전투';$('#phasePill').className='phase-pill'+(state.phase==='battle'?' battle':'')+(time<=10&&state.phase==='battle'?' urgent':'');$('#phaseBadge').textContent=state.phase==='prep'?'PREP':'BATTLE';$('#enemyFill').style.width=`${state.hp/state.rules.enemyHP*100}%`;$('#enemyValue').textContent=`${Math.max(0,state.hp).toLocaleString()} / ${state.rules.enemyHP.toLocaleString()}`;$('#lineCount').textContent=state.lineCount;$('#comboCount').textContent=state.combo;$('#totalDamage').textContent=state.totalDamage.toLocaleString();$('#lineShare').innerHTML=`${state.totalDamage?Math.round(state.lineDamage/state.totalDamage*100):0}<small>%</small>`;$('#moveCount').textContent=state.moves;for(let i=0;i<3;i++)$('#charge'+i).style.width=`${Math.min(100,state.charges[i])}%`;}
function renderTools(){const prep=state.phase==='prep';$('#prepTools').classList.toggle('hidden',!prep);$('#paintStock').textContent=state.paintStock;$$('[data-paint]').forEach(b=>{b.classList.toggle('chosen',Number(b.dataset.paint)===paint&&!leaderRemaining);b.disabled=!prep||state.paintStock<=0||state.paused;});$('#leaderBtn').disabled=!prep||(state.leaderUsed&&!leaderRemaining)||state.paused;$('#leaderBtn').innerHTML=state.prepAim?'정렬할 행 선택':leaderRemaining?`${state.rules.leaderHero===0?'불':'물'} 변환 ${leaderRemaining}칸 선택`:state.leaderUsed?'리더 사용 완료':PREP_SKILLS[state.rules.leaderHero].name;for(let h=0;h<3;h++)$('#card'+h).classList.toggle('active',h===state.rules.leaderHero&&(!!leaderRemaining||state.prepAim));$('#startBattleBtn').disabled=!prep||state.paused;$('#cancelToolBtn').hidden=paint===null&&!state.prepAim&&state.skillTarget===null;}
function applyPaint(index){if(state.phase!=='prep'||paint===null||state.locked)return;if(remaining()<=0){startBattle();return;}if(leaderRemaining){if(state.board[index]===paint){toast('이미 같은 속성 돌이에요. 다른 돌을 골라 주세요.');return;}if(state.board[index]>=state.rules.colors){toast('아이템 대신 색깔 돌을 골라 주세요.');return;}state.leaderUsed=true;state.events.push({type:'leaderConvert',index,from:state.board[index]});const targetColor=paint;state.board[index]=targetColor;showPuzzleVFX(state.rules.leaderHero,'prep',[index],index);leaderRemaining--;if(!leaderRemaining){paint=null;$('#statusText').textContent='리더 변환을 마쳤어요. 남은 준비를 이어가세요.';}}else if(state.paintStock>0){state.board[index]=paint;state.paintStock--;paint=null;$('#statusText').textContent='색칠 완료. 준비 중에는 돌이 터지지 않아요.';}selected=null;render();const cell=$(`#board [data-index="${index}"]`);cell?.animate([{transform:'scale(.83)',filter:'brightness(1.4)'},{transform:'scale(1)',filter:'brightness(1)'}],{duration:230,easing:'ease-out'});}
function skillCutin(hero=1,leader=false,active=false){$('.skill-cutin')?.remove();const skills=[['knight','돌진 베기','불의 기사'],['mage',leader?'물빛 전환':'물빛 파동','물의 마법사'],['ranger','관통 사격','숲의 정찰병']],skill=skills[hero];const el=document.createElement('div');el.className='skill-cutin skill-'+skill[0];el.innerHTML=`<img src="assets/${skill[0]}-skill-threequarter-v3.png" alt="${skill[2]} 정측면 스킬 컷인"><div><small>${leader?'PREP SKILL':active?'ACTIVE SKILL':'LINE ATTACK'}</small><strong>${leader?PREP_SKILLS[hero].name:active?SKILLS[hero].name:skill[1]}</strong><span>${leader?PREP_SKILLS[hero].description:active?SKILLS[hero].description:skill[2]}</span></div>`;el.style.animationPlayState='paused';$('.battle-scene').append(el);const cutinImage=el.querySelector('img');const playCutin=()=>{el.style.animationPlayState='running';setTimeout(()=>el.remove(),1250);};if(cutinImage.complete&&cutinImage.naturalWidth)playCutin();else{cutinImage.onload=playCutin;cutinImage.onerror=()=>el.remove();}}
function puzzlePopup(text,kind='combo',recipe=''){const board=$('#board'),body=board.parentElement;const el=document.createElement('div');el.className='puzzle-pop '+kind;el.textContent=text;const br=board.getBoundingClientRect(),pr=body.getBoundingClientRect();el.style.top=(br.top-pr.top+br.height*.23)+'px';body.append(el);if(kind==='score'){const parts=text.split(' = ');el.textContent='';if(recipe){const label=document.createElement('small');label.className='score-recipe';label.textContent=recipe;el.append(label);}if(parts.length>1){const formula=document.createElement('small');formula.textContent=parts[0]+' =';el.append(formula);}const value=document.createElement('strong');value.textContent=parts.at(-1).replace(/점$/,'');el.append(value);el.style.animation='none';const source=el.getBoundingClientRect(),enemy=$('#enemy'),target=enemy.getBoundingClientRect(),dx=target.left+target.width*.5-(source.left+source.width*.5),dy=target.top+target.height*.45-(source.top+source.height*.5);el.style.zIndex='30';el.dataset.target='enemy';const flight=el.animate([{transform:'translate(0,12px) scale(.7)',opacity:0,easing:'ease-out'},{transform:'translate(0,-12px) scale(1.06)',opacity:1,offset:.18,easing:'ease-out'},{transform:'translate(0,-22px) scale(1)',opacity:1,offset:.62,easing:'cubic-bezier(.75,0,1,.35)'},{transform:`translate(${dx}px,${dy}px) scale(.68)`,opacity:1,offset:.94,easing:'ease-out'},{transform:`translate(${dx}px,${dy}px) scale(1.03)`,opacity:0}],{duration:1250,easing:'linear',fill:'forwards'});flight.onfinish=()=>el.remove();setTimeout(()=>{if(!el.isConnected)return;enemy.animate([{transform:'translate(0,0)',filter:'brightness(1)'},{transform:'translate(7px,-3px)',filter:'brightness(1.6)',offset:.3},{transform:'translate(0,0)',filter:'brightness(1)'}],{duration:220});},1175);}else{body.querySelectorAll('.puzzle-pop.'+kind).forEach(other=>{if(other!==el)other.remove();});setTimeout(()=>el.remove(),kind==='fever-entry'?1600:1100);}}

function comboEffect(n){puzzlePopup(state.combo+' COMBO');renderPuzzleMeter();}
function tickCombo(){const now=clock();state.comboRemaining=advanceComboWindow(state.comboRemaining,(now-state.comboTick)/1000,state.resolving||state.resolvePending||state.casting.some(Boolean)||state.paused||state.warmup||state.phase!=='battle'||state.finished);state.comboTick=now;if(state.comboRemaining<=0)state.combo=0;}
function renderPuzzleMeter(){tickCombo();const now=battleElapsed(),active=state.phase==='battle'&&now<state.feverUntil;$('#liveCombo').textContent=state.combo;$('#liveChain').textContent=state.resolving?state.chain:0;$('#puzzleScore').textContent=state.score.toLocaleString()+'점';$('#game').classList.toggle('fever-active',active);$('#board').dataset.feverLabel=active?'FEVER ×'+state.rules.feverMultiplier+' · '+Math.max(0,state.feverUntil-now).toFixed(1)+'s':'';let feverFrame=$('.fever-spectacle');if(!feverFrame){feverFrame=document.createElement('div');feverFrame.className='fever-spectacle';feverFrame.setAttribute('aria-hidden','true');$('#game').append(feverFrame);}feverFrame.hidden=!active;$('#feverStatus').textContent=active?'FEVER ×'+state.rules.feverMultiplier+' · '+Math.max(0,state.feverUntil-now).toFixed(1)+'초':'';}
function addCombo(chain){tickCombo();const now=battleElapsed();state.combo++;state.comboRemaining=state.rules.comboWindow;if(state.combo>=state.rules.feverThreshold&&now>=state.feverUntil){state.feverUntil=now+state.rules.feverSeconds;state.events.push({type:'fever',combo:state.combo,t:now,multiplier:state.rules.feverMultiplier});puzzlePopup('FEVER TIME!','fever-entry');$('#game').animate([{filter:'brightness(1)'},{filter:'brightness(1.3)',offset:.25},{filter:'brightness(1)'}],{duration:650,easing:'ease-out'});}comboEffect(chain);return now<state.feverUntil?state.rules.feverMultiplier:1;}
function selectLeader(){return selectPrepSkill(state.rules.leaderHero);}
function selectPrepSkill(hero){if(state.phase!=='prep'||state.paused||state.finished||state.warmup)return;if(hero!==state.rules.leaderHero){toast('준비 스킬은 선택한 리더만 쓸 수 있어요.');return;}if(state.leaderUsed){toast('이번 준비 페이즈에서 이미 사용했어요.');return;}selected=null;paint=null;leaderRemaining=0;if(hero===2){const index=randomSkillTarget(hero,'prep',state.board,state.ids,new Set(),state.rng,state.rules.columns);if(index===null){toast('모든 행이 이미 정렬돼 있어요.');return;}skillCutin(hero,true);usePrepRow(index);}else{const color=PREP_SKILLS[hero].color,candidates=state.board.map((_,i)=>i).filter(i=>state.board[i]<state.rules.colors&&state.board[i]!==color);if(!candidates.length){toast('변환할 돌이 없어요.');return;}skillCutin(hero,true);leaderRemaining=Math.min(2,candidates.length);paint=color;while(leaderRemaining){const pick=Math.floor(state.rng()*candidates.length),index=candidates.splice(pick,1)[0];applyPaint(index);}}$('#statusText').textContent=PREP_SKILLS[hero].name+' · 무작위 대상 적용 완료';render();}

function usePrepRow(index){const hero=state.rules.leaderHero,plan=planTargetSkill(hero,'prep',state.board,state.ids,index);if(!plan){toast('이미 정렬된 행이에요. 다른 행을 골라 주세요.');return;}const previous=captureStones($('#board')),before=state.board.slice(),next=applyPuzzlePlan(state.board,state.ids,plan);state.board=next.board;state.ids=next.ids;state.leaderUsed=true;state.prepAim=false;leaderRemaining=0;state.events.push({type:'prepSkill',hero,plan,before,after:state.board.slice()});showPuzzleVFX(hero,'prep',plan.cells,index);renderBoard(false,previous,{kind:'skillSort'});renderTools();}
function scheduleFreeResolve(token){clearTimeout(freeResolveTimer);state.freeReadyAt=clock()+1000;const check=()=>{if(token!==generation||state.finished||state.phase!=='battle')return;if(state.paused||state.resolving||clock()<state.freeReadyAt){freeResolveTimer=setTimeout(check,50);return;}resolve(token);};freeResolveTimer=setTimeout(check,1000);}
function tickSkills(){const now=clock(),dt=Math.max(0,Math.min(.2,(now-state.skillTick)/1000));state.skillTick=now;if(state.phase!=='battle'||state.warmup||state.paused||state.finished)return;state.skillClock+=dt;for(let h=0;h<3;h++)state.charges[h]=Math.min(100,state.charges[h]+dt*3);}

function renderSkillHUD(){for(let h=0;h<3;h++){const card=$('#card'+h);let label=card.querySelector('.skill-state');if(!label){label=document.createElement('strong');label.className='skill-state';card.append(label);}let badge=card.querySelector('em');if(!badge){badge=document.createElement('em');badge.textContent='LEADER';card.append(badge);}badge.hidden=h!==state.rules.leaderHero;const status=skillAvailability(state.charges[h],state.skillReadyAt[h],state.skillClock),prep=state.phase==='prep';const ready=!prep&&!state.finished&&!state.warmup&&status.ready&&!state.casting[h],wasReady=card.classList.contains('skill-ready');card.classList.toggle('skill-ready',ready);if(ready&&!wasReady){card.animate([{transform:'translateY(0) scale(1)'},{transform:'translateY(-7px) scale(1.16)',offset:.35},{transform:'translateY(1px) scale(.98)',offset:.7},{transform:'translateY(0) scale(1)'}],{duration:540,easing:'ease-out'});const flash=document.createElement('div');flash.className='ready-sweep';flash.setAttribute('aria-hidden','true');card.append(flash);setTimeout(()=>flash.remove(),800);}card.classList.toggle('skill-casting',state.casting[h]);label.textContent=prep?(h===state.rules.leaderHero?(state.leaderUsed?'준비 사용 완료':PREP_SKILLS[h].name):'준비 리더 아님'):state.casting[h]?'발동 중':state.skillTarget===h?(SKILLS[h].axis==='row'?'행 선택':'열 선택'):status.cooldown>0?status.cooldown.toFixed(1)+'s':status.ready?'READY!':Math.floor(status.gauge)+'%';card.dataset.gauge=state.charges[h].toFixed(2);card.dataset.cooldown=status.cooldown.toFixed(2);card.dataset.skillUses=state.skillUses[h];card.title=prep?PREP_SKILLS[h].name+' · '+PREP_SKILLS[h].description:SKILLS[h].name+' · '+SKILLS[h].description+' · 쿨타임 '+SKILLS[h].cooldown+'초';card.setAttribute('aria-label',(prep?PREP_SKILLS[h].name:SKILLS[h].name)+' · '+label.textContent);}let buffs=$('#skillBuffs');if(!buffs){buffs=document.createElement('div');buffs.id='skillBuffs';buffs.className='skill-buffs';$('.battle-scene').append(buffs);}buffs.textContent=state.skillNotice||'';$('#enemy').classList.remove('exposed');}

function useSkill(hero){if(state.finished||state.paused)return;if(state.phase!=='battle'){selectPrepSkill(hero);return;}if(state.warmup||state.casting[hero])return;if(state.skillTarget===hero){cancelSkillTarget();return;}const status=skillAvailability(state.charges[hero],state.skillReadyAt[hero],state.skillClock);if(!status.ready){toast(status.cooldown>0?'쿨타임 '+status.cooldown.toFixed(1)+'초 남았어요.':'게이지 '+Math.floor(status.gauge)+'% · 같은 속성 돌을 지우면 빨리 충전돼요.');return;}const index=randomSkillTarget(hero,'battle',state.board,state.ids,new Set(state.pendingVisual.keys()),state.rng,state.rules.columns);if(index===null){toast(hero===0?'지울 빨간 불 블록이 없어요.':'지금은 적용할 돌이 없어요.');return;}state.skillTarget=hero;selected=null;castTargetSkill(index);}

function cancelSkillTarget(){state.skillTarget=null;state.skillNotice='';$('#board').querySelectorAll('.skill-aim').forEach(el=>el.classList.remove('skill-aim'));renderBoard();renderTools();}
function previewSkillTarget(index){if(state.skillTarget===null&&!state.prepAim)return;const axis=state.prepAim?'row':SKILLS[state.skillTarget].axis;for(const el of $('#board').querySelectorAll('.tile')){const i=Number(el.dataset.index);el.classList.toggle('skill-aim',axis==='row'?Math.floor(i/6)===Math.floor(index/6):i%6===index%6);}}
function detectionBoard(){return state.board.map((c,i)=>state.pendingVisual.has(state.ids[i])?null:c);}
