function clearGroups(found){const normal=found.allCells.filter(i=>!(found.itemCells||[]).includes(i)),left=new Set(normal),groups=[];while(left.size){const seed=left.values().next().value,cells=[seed],color=state.board[seed];left.delete(seed);for(let k=0;k<cells.length;k++)for(const j of [...left])if(state.board[j]===color&&adjacent(cells[k],j,state.rules.columns)){left.delete(j);cells.push(j);}groups.push({color,cells,axis:'connected',item:false});}const extra=found.allCells.filter(i=>(found.itemCells||[]).includes(i));if(extra.length)groups.push({cells:extra,item:true});return groups;}
async function clearGroup(group,token){const ids=group.ids;group={...group,cells:ids.map(uid=>state.ids.indexOf(uid)).filter(i=>i>=0)};if(!group.item){connectLines($('#board'),[group]);$('#statusText').textContent=`${names[group.color]} ${ids.length}개 연결`; }else $('#statusText').textContent='아이템 범위에 닿은 블록 제거';for(const uid of ids){const i=state.ids.indexOf(uid);if(i>=0)mark([i],'charging');}if(!await delay(170,token))return false;for(const uid of ids){const i=state.ids.indexOf(uid);if(i<0)continue;burst($('#board'),[i],state.board,!group.item&&ids.length>=5);mark([i],'clearing');tone('match');if(!await delay(70,token))return false;}if(!await delay(120,token))return false;return true;}
